// INSTRUCTIONS:
//   1. Upload ALL THREE parts to public_html:
//      deploy1.php  deploy2.php  deploy3.php
//   2. Visit yourdomain.com/deploy1.php  (runs all 3 parts)
//   3. Delete all 3 deploy files after success!
// ================================================================

set_time_limit(120);
$base = __DIR__;

function fmWrite($base, $rel, $gz_b64) {
    $dir = dirname("$base/$rel");
    if (!is_dir($dir)) mkdir($dir, 0755, true);
    return file_put_contents("$base/$rel", gzdecode(base64_decode($gz_b64))) !== false;
}

$ok = []; $errors = [];
$files = [
    'assets/css/style.css' => '',
    'dashboard.html' => '',
    'index.html' => '',
    'register.html' => '',
];
foreach ($files as $r => $b) {{ if(fmWrite($base,$r,$b)) $ok[]=$r; else $errors[]=$r; }}
$all_ok = array_merge($_SESSION['fm_ok']??[], $ok);
$all_err = array_merge($_SESSION['fm_err']??[], $errors);
session_start();
$_SESSION['fm_ok'] = $all_ok;
$_SESSION['fm_err'] = $all_err;
?>
